import { normalizeDueDate } from './due-date.js';

const heading = document.querySelector('#heading');
const alert = document.querySelector('#alert');
const list = document.querySelector('#project-list');
const detail = document.querySelector('#project-detail');
const projects = document.querySelector('#projects');
const form = document.querySelector('#create-project');
const nameInput = document.querySelector('#project-name');
const renameForm = document.querySelector('#rename-project');
const newNameInput = document.querySelector('#new-project-name');
const taskForm = document.querySelector('#create-task');
const titleInput = document.querySelector('#task-title');
const taskFilter = document.querySelector('#task-filter');
const priorityFilter = document.querySelector('#priority-filter');
const dueRangeForm = document.querySelector('#due-range');
const dueFromInput = document.querySelector('#due-from');
const dueThroughInput = document.querySelector('#due-through');
let dueFrom = '';
let dueThrough = '';
const defaultPrioritySelect = document.querySelector('#default-task-priority');
let defaultTaskPriority = 'Normal';
const tasksElement = document.querySelector('#tasks');
const projectId = window.location.pathname.match(/^\/projects\/([1-9]\d*)$/)?.[1];
let tasks = [];
let projectItems = [];
let archived = false;
const projectFilter = document.querySelector('#project-filter');

function showError(message) {
  alert.textContent = message;
  alert.hidden = false;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Request failed');
  return result;
}

function renderProjects() {
  const items = projectItems.filter((project) => project.archived === (projectFilter.value === 'archived'));
  projects.replaceChildren();
  document.querySelector('#empty').hidden = items.length > 0;
  for (const project of items) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => {
      window.location.assign(`/projects/${project.id}`);
    });
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const archiveButton = document.createElement('button');
    archiveButton.type = 'button';
    archiveButton.textContent = project.archived ? 'Restore project' : 'Archive project';
    archiveButton.addEventListener('click', async () => {
      alert.hidden = true;
      archiveButton.disabled = true;
      try {
        await request(`/api/projects/${project.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ archived: !project.archived }),
        });
        await loadProjects();
      } catch (error) {
        showError(error.message);
      } finally {
        archiveButton.disabled = false;
      }
    });
    row.append(name, summary, open, archiveButton);
    projects.append(row);
  }
}

async function loadProjects() {
  projectItems = await request('/api/projects');
  renderProjects();
}

projectFilter.addEventListener('change', renderProjects);

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  alert.hidden = true;
  const name = nameInput.value.trim();
  if (!name) {
    showError('Project name is required');
    return;
  }
  const button = form.querySelector('button');
  button.disabled = true;
  try {
    await request('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    nameInput.value = '';
    await loadProjects();
    nameInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    button.disabled = false;
  }
});

function showProjectName(name) {
  heading.textContent = name;
  document.title = `${name} — Workboard`;
}

renameForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (archived) return;
  alert.hidden = true;
  const name = newNameInput.value.trim();
  if (!name) {
    showError('Project name is required');
    return;
  }
  const button = renameForm.querySelector('button');
  button.disabled = true;
  try {
    const project = await request(`/api/projects/${projectId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    showProjectName(project.name);
    newNameInput.value = '';
  } catch (error) {
    showError(error.message);
  } finally {
    button.disabled = archived;
  }
});

defaultPrioritySelect.addEventListener('change', async () => {
  if (archived) return;
  alert.hidden = true;
  defaultPrioritySelect.disabled = true;
  try {
    const project = await request(`/api/projects/${projectId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ defaultTaskPriority: defaultPrioritySelect.value }),
    });
    defaultTaskPriority = project.defaultTaskPriority;
  } catch (error) {
    showError(error.message);
  } finally {
    defaultPrioritySelect.value = defaultTaskPriority;
    defaultPrioritySelect.disabled = archived;
  }
});

dueRangeForm.addEventListener('submit', (event) => {
  event.preventDefault();
  alert.hidden = true;
  const from = normalizeDueDate(dueFromInput.value);
  const through = normalizeDueDate(dueThroughInput.value);
  if (from === null || through === null) {
    showError('Due range must use valid YYYY-MM-DD dates');
    return;
  }
  if (from && through && from > through) {
    showError('Due from must not be after Due through');
    return;
  }
  dueFrom = from;
  dueThrough = through;
  dueFromInput.value = from;
  dueThroughInput.value = through;
  renderTasks();
});

function renderTasks() {
  tasksElement.replaceChildren();
  for (const task of tasks) {
    if (taskFilter.value === 'open' && task.completed) continue;
    if (taskFilter.value === 'completed' && !task.completed) continue;
    if (priorityFilter.value !== 'all' && task.priority !== priorityFilter.value) continue;
    if ((dueFrom || dueThrough) && !task.dueDate) continue;
    if (dueFrom && task.dueDate < dueFrom) continue;
    if (dueThrough && task.dueDate > dueThrough) continue;
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = archived;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      alert.hidden = true;
      checkbox.disabled = true;
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        task.completed = saved.completed;
        renderTasks();
      } catch (error) {
        checkbox.checked = task.completed;
        showError(error.message);
      } finally {
        checkbox.disabled = false;
      }
    });
    const renameTaskForm = document.createElement('form');
    renameTaskForm.className = 'rename-task';
    const label = document.createElement('label');
    label.htmlFor = `new-task-title-${task.id}`;
    label.textContent = 'New task title';
    const input = document.createElement('input');
    input.id = label.htmlFor;
    input.type = 'text';
    input.disabled = archived;
    const button = document.createElement('button');
    button.type = 'submit';
    button.textContent = 'Rename task';
    button.disabled = archived;
    renameTaskForm.append(label, input, button);
    renameTaskForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (archived) return;
      alert.hidden = true;
      const newTitle = input.value.trim();
      if (!newTitle) {
        showError('Task title is required');
        return;
      }
      button.disabled = true;
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title: newTitle }),
        });
        task.title = saved.title;
        title.textContent = saved.title;
        checkbox.setAttribute('aria-label', `Complete ${saved.title}`);
        input.value = '';
      } catch (error) {
        showError(error.message);
      } finally {
        button.disabled = archived;
      }
    });
    const priorityLabel = document.createElement('label');
    priorityLabel.htmlFor = `task-priority-${task.id}`;
    priorityLabel.textContent = 'Task priority';
    const prioritySelect = document.createElement('select');
    prioritySelect.id = priorityLabel.htmlFor;
    prioritySelect.disabled = archived;
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      prioritySelect.append(option);
    }
    prioritySelect.value = task.priority;
    prioritySelect.addEventListener('change', async () => {
      alert.hidden = true;
      prioritySelect.disabled = true;
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ priority: prioritySelect.value }),
        });
        task.priority = saved.priority;
        renderTasks();
      } catch (error) {
        showError(error.message);
      } finally {
        prioritySelect.value = task.priority;
        prioritySelect.disabled = archived;
      }
    });
    const dueDateForm = document.createElement('form');
    dueDateForm.className = 'task-due-date';
    const dueDateLabel = document.createElement('label');
    dueDateLabel.htmlFor = `task-due-date-${task.id}`;
    dueDateLabel.textContent = 'Task due date';
    const dueDateInput = document.createElement('input');
    dueDateInput.id = dueDateLabel.htmlFor;
    dueDateInput.type = 'text';
    dueDateInput.value = task.dueDate;
    dueDateInput.disabled = archived;
    const saveDueDateButton = document.createElement('button');
    saveDueDateButton.type = 'submit';
    saveDueDateButton.textContent = 'Save due date';
    saveDueDateButton.disabled = archived;
    dueDateForm.append(dueDateLabel, dueDateInput, saveDueDateButton);
    dueDateForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (archived) return;
      alert.hidden = true;
      saveDueDateButton.disabled = true;
      try {
        const saved = await request(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ dueDate: dueDateInput.value }),
        });
        task.dueDate = saved.dueDate;
        dueDateInput.value = saved.dueDate;
        renderTasks();
      } catch (error) {
        showError(error.message);
      } finally {
        saveDueDateButton.disabled = archived;
      }
    });
    const moveForm = document.createElement('form');
    moveForm.className = 'move-task';
    const destinationLabel = document.createElement('label');
    destinationLabel.htmlFor = `destination-project-${task.id}`;
    destinationLabel.textContent = 'Destination project';
    const destinationSelect = document.createElement('select');
    destinationSelect.id = destinationLabel.htmlFor;
    const destinations = projectItems.filter((project) => !project.archived && String(project.id) !== projectId);
    for (const project of destinations) {
      const option = document.createElement('option');
      option.value = String(project.id);
      option.textContent = project.name;
      destinationSelect.append(option);
    }
    if (destinations.length) destinationSelect.value = String(destinations[0].id);
    const moveButton = document.createElement('button');
    moveButton.type = 'submit';
    moveButton.textContent = 'Move task';
    destinationSelect.disabled = moveButton.disabled = archived || destinations.length === 0;
    moveForm.append(destinationLabel, destinationSelect, moveButton);
    moveForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (archived || !destinations.length) return;
      alert.hidden = true;
      moveButton.disabled = true;
      try {
        await request(`/api/projects/${projectId}/tasks/${task.id}/move`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ destinationProjectId: Number(destinationSelect.value) }),
        });
        tasks = tasks.filter((item) => item.id !== task.id);
        renderTasks();
      } catch (error) {
        showError(error.message);
      } finally {
        moveButton.disabled = archived || destinations.length === 0;
      }
    });
    row.append(checkbox, title, renameTaskForm, priorityLabel, prioritySelect, dueDateForm, moveForm);
    tasksElement.append(row);
  }
}

taskFilter.addEventListener('change', renderTasks);
priorityFilter.addEventListener('change', renderTasks);
taskForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (archived) return;
  alert.hidden = true;
  const title = titleInput.value.trim();
  if (!title) {
    showError('Task title is required');
    return;
  }
  const button = taskForm.querySelector('button');
  button.disabled = true;
  try {
    const task = await request(`/api/projects/${projectId}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title }),
    });
    tasks.push(task);
    titleInput.value = '';
    renderTasks();
    titleInput.focus();
  } catch (error) {
    showError(error.message);
  } finally {
    button.disabled = false;
  }
});

document.querySelector('#back').addEventListener('click', () => window.location.assign('/'));

async function loadPage() {
  if (projectId) {
    const project = await request(`/api/projects/${projectId}`);
    archived = project.archived;
    defaultTaskPriority = project.defaultTaskPriority;
    defaultPrioritySelect.value = defaultTaskPriority;
    defaultPrioritySelect.disabled = archived;
    document.querySelector('#archived-notice').hidden = !archived;
    taskForm.querySelector('button').disabled = archived;
    newNameInput.disabled = archived;
    renameForm.querySelector('button').disabled = archived;
    showProjectName(project.name);
    projectItems = await request('/api/projects');
    tasks = await request(`/api/projects/${projectId}/tasks`);
    renderTasks();
    detail.hidden = false;
  } else {
    list.hidden = false;
    await loadProjects();
  }
}

loadPage().catch((error) => showError(error.message));

import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { normalizeDueDate } from './due-date.js';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK(length(trim(name)) > 0)
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK(length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
`);
// Upgrade databases created before project archiving was introduced.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0, 1))');
}
// Existing projects keep Normal as their default without changing saved tasks.
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'defaultTaskPriority')) {
  database.exec("ALTER TABLE projects ADD COLUMN defaultTaskPriority TEXT NOT NULL DEFAULT 'Normal' CHECK(defaultTaskPriority IN ('Low', 'Normal', 'High'))");
}
// Existing tasks receive Normal when upgrading from a database without priorities.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High'))");
}
// Empty text represents no due date for new and existing tasks.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'dueDate')) {
  database.exec("ALTER TABLE tasks ADD COLUMN dueDate TEXT NOT NULL DEFAULT ''");
}
// Per-project positions preserve old creation order and allow moves to append.
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
  database.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0; UPDATE tasks SET position = id');
}
const projectSelect = `SELECT projects.id, projects.name, projects.archived, projects.defaultTaskPriority,
  COUNT(tasks.id) AS totalCount, COALESCE(SUM(tasks.completed), 0) AS completedCount
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id`;
const listProjects = database.prepare(`${projectSelect} GROUP BY projects.id ORDER BY projects.id`);
const findProject = database.prepare(`${projectSelect} WHERE projects.id = ? GROUP BY projects.id`);
const updateProject = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const updateDefaultTaskPriority = database.prepare('UPDATE projects SET defaultTaskPriority = ? WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed, priority, dueDate FROM tasks WHERE project_id = ? ORDER BY position, id');
const findTask = database.prepare('SELECT id, title, completed, priority, dueDate FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = database.prepare(`INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM tasks WHERE project_id = ?))`);
const moveTask = database.prepare(`UPDATE tasks SET project_id = ?,
  position = (SELECT COALESCE(MAX(position), 0) + 1 FROM tasks WHERE project_id = ?)
  WHERE project_id = ? AND id = ?`);
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE project_id = ? AND id = ?');
const updateTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE project_id = ? AND id = ?');
const updateTaskDueDate = database.prepare('UPDATE tasks SET dueDate = ? WHERE project_id = ? AND id = ?');
const taskJson = (task) => ({ ...task, completed: Boolean(task.completed) });
const projectJson = (project) => ({ ...project, archived: Boolean(project.archived) });

function json(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

async function readJson(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 64 * 1024) {
      const error = new Error('Request is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const assets = new Map([
  ['/', ['index.html', 'text/html']],
  ['/app.js', ['app.js', 'text/javascript']],
  ['/due-date.js', ['due-date.js', 'text/javascript']],
  ['/style.css', ['style.css', 'text/css']],
]);

const server = createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && path === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (path === '/api/projects' && request.method === 'GET') {
      return json(response, 200, listProjects.all().map(projectJson));
    }
    if (path === '/api/projects' && request.method === 'POST') {
      const input = await readJson(request);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(response, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(response, 201, projectJson(findProject.get(result.lastInsertRowid)));
    }
    const moveMatch = path.match(/^\/api\/projects\/([1-9]\d*)\/tasks\/([1-9]\d*)\/move$/);
    if (moveMatch && request.method === 'POST') {
      const [, projectId, taskId] = moveMatch;
      const input = await readJson(request);
      // Validate after reading the body; validation and the update run synchronously.
      const source = findProject.get(projectId);
      if (!source) return json(response, 404, { error: 'Project not found' });
      if (source.archived) return json(response, 409, { error: 'Archived project is read-only' });
      if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
      if (!Number.isSafeInteger(input?.destinationProjectId) || input.destinationProjectId < 1) {
        return json(response, 400, { error: 'Destination project is required' });
      }
      const destination = findProject.get(input.destinationProjectId);
      if (!destination) return json(response, 404, { error: 'Destination project not found' });
      if (destination.id === source.id || destination.archived) {
        return json(response, 409, { error: 'Destination must be another active project' });
      }
      moveTask.run(destination.id, destination.id, projectId, taskId);
      return json(response, 200, taskJson(findTask.get(destination.id, taskId)));
    }
    const tasksMatch = path.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      const project = findProject.get(projectId);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (project.archived && ['POST', 'PATCH'].includes(request.method)) {
        return json(response, 409, { error: 'Archived project is read-only' });
      }
      if (!taskId && request.method === 'GET') {
        return json(response, 200, listTasks.all(projectId).map(taskJson));
      }
      if (!taskId && request.method === 'POST') {
        const input = await readJson(request);
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(response, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title, project.defaultTaskPriority, projectId);
        return json(response, 201, taskJson(findTask.get(projectId, result.lastInsertRowid)));
      }
      if (taskId && request.method === 'PATCH') {
        if (!findTask.get(projectId, taskId)) return json(response, 404, { error: 'Task not found' });
        const input = await readJson(request);
        const fields = ['title', 'completed', 'priority', 'dueDate'].filter((field) => Object.hasOwn(input ?? {}, field));
        if (fields.length > 1) {
          return json(response, 400, { error: 'Task edits must be separate requests' });
        }
        if (Object.hasOwn(input ?? {}, 'dueDate')) {
          const dueDate = normalizeDueDate(input.dueDate);
          if (dueDate === null) {
            return json(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
          }
          updateTaskDueDate.run(dueDate, projectId, taskId);
        } else if (Object.hasOwn(input ?? {}, 'priority')) {
          if (!['Low', 'Normal', 'High'].includes(input.priority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          updateTaskPriority.run(input.priority, projectId, taskId);
        } else if (Object.hasOwn(input ?? {}, 'title')) {
          const title = typeof input.title === 'string' ? input.title.trim() : '';
          if (!title) return json(response, 400, { error: 'Task title is required' });
          renameTask.run(title, projectId, taskId);
        } else {
          if (typeof input?.completed !== 'boolean') {
            return json(response, 400, { error: 'Completed must be a boolean' });
          }
          updateTask.run(Number(input.completed), projectId, taskId);
        }
        return json(response, 200, taskJson(findTask.get(projectId, taskId)));
      }
    }
    const projectMatch = path.match(/^\/api\/projects\/([1-9]\d*)$/);
    if (projectMatch && ['GET', 'PATCH'].includes(request.method)) {
      const project = findProject.get(projectMatch[1]);
      if (!project) return json(response, 404, { error: 'Project not found' });
      if (request.method === 'PATCH') {
        const input = await readJson(request);
        const fields = ['name', 'archived', 'defaultTaskPriority'].filter((field) => Object.hasOwn(input ?? {}, field));
        if (fields.length > 1) {
          return json(response, 400, { error: 'Project edits must be separate requests' });
        }
        if (Object.hasOwn(input ?? {}, 'defaultTaskPriority')) {
          if (project.archived) {
            return json(response, 409, { error: 'Archived project is read-only' });
          }
          if (!['Low', 'Normal', 'High'].includes(input.defaultTaskPriority)) {
            return json(response, 400, { error: 'Priority must be Low, Normal, or High' });
          }
          updateDefaultTaskPriority.run(input.defaultTaskPriority, project.id);
          project.defaultTaskPriority = input.defaultTaskPriority;
        } else if (Object.hasOwn(input ?? {}, 'name')) {
          if (project.archived) {
            return json(response, 409, { error: 'Archived project is read-only' });
          }
          const name = typeof input.name === 'string' ? input.name.trim() : '';
          if (!name) return json(response, 400, { error: 'Project name is required' });
          renameProject.run(name, project.id);
          project.name = name;
        } else {
          if (typeof input?.archived !== 'boolean') {
            return json(response, 400, { error: 'Archived must be a boolean' });
          }
          updateProject.run(Number(input.archived), project.id);
          project.archived = input.archived;
        }
      }
      return json(response, 200, projectJson(project));
    }
    if (request.method === 'GET') {
      const asset = /^\/projects\/[1-9]\d*$/.test(path)
        ? assets.get('/')
        : assets.get(path);
      if (asset) {
        const content = await readFile(new URL(`./public/${asset[0]}`, import.meta.url));
        response.writeHead(200, { 'Content-Type': `${asset[1]}; charset=utf-8` });
        return response.end(content);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, { error: error.status ? error.message : 'Internal server error' });
  }
});

